# D3 sparse coords, test life next generations
coords=[(1,2),(1,7),(3,2),(3,5),(3,11),(5,7),(6,4),(6,6),(6,7),(6,8),(6,10),(7,6),(7,8),(8,11),(8,13),(13,4),(13,8),(13,13)]
a=np.zeros((15,15),int)
for r,c in coords:a[r,c]=1
outcoords={(5,8),(5,9),(6,9),(6,10),(7,8),(7,9)}
def life(x):
    from scipy.signal import convolve2d
    n=convolve2d(x,np.ones((3,3),int),mode='same')-x
    return ((n==3)|((x==1)&(n==2))).astype(int)
